import React, { useLayoutEffect, useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, ExternalLink } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useLenisRef } from '../context/ScrollContext';
import { CORE_PROJECTS } from '../constants';
import content from '../i18n/content';
import './ProjectDetail.css';

function SpriteRunner({ dir, frameCount, fps, name }) {
  const [frame, setFrame] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      setFrame(f => (f + 1) % frameCount);
    }, 1000 / fps);
    return () => clearInterval(id);
  }, [frameCount, fps]);

  const padded = String(frame).padStart(2, '0');
  const src = `${process.env.PUBLIC_URL}/${dir}/frame-${padded}.svg`;

  return (
    <img
      src={src}
      alt={name}
      className="sprite-runner"
      draggable={false}
    />
  );
}

export default function ProjectDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { lang } = useLanguage();
  const lenisRef = useLenisRef();

  useLayoutEffect(() => {
    const lenis = lenisRef.current;
    if (lenis) {
      lenis.resize();
      lenis.scrollTo(0, { immediate: true });
    } else {
      window.scrollTo(0, 0);
    }
  }, [lenisRef]);

  const handleBack = () => navigate('/', { state: { scrollTo: 'projects' } });
  const t = content[lang].projects;

  const projectData = CORE_PROJECTS[id];
  const projectCopy = t.items[id];

  if (!projectData || !projectCopy) {
    return (
      <div className="project-detail-not-found">
        <p>{t.notFound}</p>
        <button type="button" onClick={handleBack} className="project-detail-back">
          <ArrowLeft size={18} />
          <span>{t.backToPortfolio}</span>
        </button>
      </div>
    );
  }

  return (
    <div className="project-detail-page">
      <button type="button" className="project-detail-back" onClick={handleBack}>
        <ArrowLeft size={18} />
        <span>{t.back}</span>
      </button>

      <h1>{projectCopy.title}</h1>
      <p className="project-detail-description">{projectCopy.description}</p>

      <h2>{t.keyAchievements}</h2>
      <ul>
        {projectCopy.achievements.map((line, index) => (
          <li key={index}>{line}</li>
        ))}
      </ul>

      <p className="project-detail-stack">
        <strong>{t.techStack}</strong> {projectData.stack.join(', ')}
      </p>

      <a href={projectData.url} target="_blank" rel="noopener noreferrer" className="project-detail-github">
        {t.viewGithub}
        <ExternalLink size={16} />
      </a>

      {projectData.screenshot && (
        <img
          src={projectData.screenshot}
          alt={`${projectCopy.title} screenshot`}
          className="project-detail-screenshot"
          loading="lazy"
        />
      )}

      {projectData.runners && (
        <div className="project-detail-runners">
          {projectData.runners.players.map((player) => (
            <SpriteRunner
              key={player.dir}
              dir={player.dir}
              name={player.name}
              frameCount={projectData.runners.frameCount}
              fps={projectData.runners.fps}
            />
          ))}
        </div>
      )}

      {!projectData.runners && projectData.avatars?.length > 0 && (
        <div className="project-detail-avatars">
          {projectData.avatars.map((src, i) => (
            <img
              key={i}
              src={src}
              alt={`Player ${i + 1}`}
              className="project-detail-avatar-img"
              loading="lazy"
            />
          ))}
        </div>
      )}
    </div>
  );
}
